const inventory1 = ['e1:1','e1:2','e1:3','e1:4','e1:5','e1:6','e1:7','e1:8','e1:9','e1:10','e1:11','e1:12','e2:1','e2:2','e2:3','e2:4','e2:5','e2:6','e2:7','e2:8','e2:9','e2:10','e3:1','e3:2','e3:3','e3:4','e3:5','e3:6','e3:7','e3:8','e3:9','e3:10','e3:11','e3:12','e3:13'];
const inventory2 = ['e1:1','e1:2','e1:3','e1:4','e1:5','e1:6','e1:7','e1:8','e1:9','e1:10','e1:11','e2:1','e2:2','e2:3','e2:4','e2:5','e2:6','e2:7','e2:8','e2:9','e2:10','e3:1','e3:2','e3:3','e3:4','e3:5','e3:6','e3:7','e3:8','e3:9','e3:10','e3:11','e3:12','e3:13'];
function a(question, title, prompt, value, hints, resolution, writingPrompt) {
  return answer(title, prompt, value, hints, resolution, {question,guidance:hints[0],pitfall:hints[1],...(writingPrompt?{writingPrompt}:{})});
}
function p(question,title,prompt,name,params,solution,cases,hints,resolution,extras={}) {
  return python(title,prompt,name,`def ${name}(${params}):\n    pass`,solution,cases,hints,resolution,{question,guidance:hints[0],pitfall:hints[1],...extras});
}
function s(question,title,prompt,setup,solution,expected,hints,resolution) {
  return sql(title,prompt,setup,solution,expected,hints,resolution,{question,guidance:hints[0],pitfall:hints[1]});
}
